#[test]
#[ignore]
fn measure_empty_reply_callback() -> Result<(), Box<dyn std::error::Error>> {
    let mut state = live_state(&cold_plan()?, reply_input())?;
    let mut writer = RecordingWriter::default();
    let iterations = 5_000_000_u64;
    let started = std::time::Instant::now();
    for _ in 0..iterations {
        std::hint::black_box(std::hint::black_box(&mut state).deliver_reply(
            std::hint::black_box(50),
            std::hint::black_box(0),
            std::hint::black_box(&mut writer),
        )?);
    }
    println!("empty_reply_iterations={iterations} elapsed_ns={}", started.elapsed().as_nanos());
    assert_eq!(writer.delivery_icount, None);
    assert_eq!(state.catalog().total_completed_requests(), 0);
    Ok(())
}
